def GetCoreType(board):
    if board.endswith('_lcpu'):
        core = 'LCPU'
    elif board.endswith('_hcpu'):
        core = 'HCPU'
    elif board.endswith('_acpu'):
        core = 'ACPU'
    else:
        core = 'HCPU'

    return core

